import java.io.BufferedReader
import java.io.InputStreamReader
import java.io.PrintWriter
import java.util.StringTokenizer

fun main() {
    val solver = Solver()
    solver.run()
}

class Solver {
    private val ONLINE_JUDGE: Boolean = System.getProperty("ONLINE_JUDGE") != null
    private lateinit var in: BufferedReader
    private lateinit var out: PrintWriter
    private var tok: StringTokenizer = StringTokenizer("")

    private fun init() {
        if (ONLINE_JUDGE) {
            in = BufferedReader(InputStreamReader(System.`in`))
            out = PrintWriter(System.out)
        } else {
            in = BufferedReader(java.io.FileReader("input.txt"))
            out = PrintWriter("output.txt")
        }
    }

    private fun readString(): String? {
        while (!tok.hasMoreTokens()) {
            val line = in.readLine() ?: return null
            tok = StringTokenizer(line)
        }
        return tok.nextToken()
    }

    private fun readInt(): Int = readString()!!.toInt()
    private fun readLong(): Long = readString()!!.toLong()

    fun run() {
        try {
            init()
            solve()
            out.close()
        } catch (e: Exception) {
            e.printStackTrace()
            System.exit(-1)
        }
    }

    private fun solve() {
        val l = readInt()
        val r = readInt()

        val n = 9
        val ten = LongArray(n + 1)
        ten[0] = 1
        for (i in 1..n) {
            ten[i] = 10 * ten[i - 1]
        }

        var answer = 0L
        val luckyNumbers = mutableListOf<Long>()

        for (length in 1..n) {
            for (cur in 0 until (1 shl length)) {
                var value = 0L
                for (j in 0 until length) {
                    if ((cur and (1 shl j)) == (1 shl j)) {
                        value += ten[j] * 7
                    } else {
                        value += ten[j] * 4
                    }
                }
                luckyNumbers.add(value)
            }
        }

        luckyNumbers.add(4444444444L)

        var lastNumber = l.toLong()

        for (luckyNumber in luckyNumbers) {
            if (luckyNumber > r) {
                answer += (r - lastNumber + 1) * luckyNumber
                break
            }
            if (luckyNumber >= l) {
                answer += (luckyNumber - lastNumber + 1) * luckyNumber
                lastNumber = luckyNumber + 1
            }
        }

        out.println(answer)
    }
}

